type compiledGraph struct {
	runID        string
	boundary     string
	maxStepBytes int
	agents       map[string]AgentSpec
	agentOrder   []string
	predecessors map[string][]string
	successors   map[string][]string
	edgeIDs      map[string]string
	sources      []string
}

func compileGraph(spec GraphSpec) (*compiledGraph, error) {
	runID := strings.TrimSpace(spec.RunID)
	if runID == "" {
		runID = "run_streamma"
	}
	protocol := strings.TrimSpace(spec.Protocol)
	if protocol == "" {
		protocol = ProtocolStream
	}
	if protocol != ProtocolStream {
		return nil, fmt.Errorf("unsupported streamma protocol: %s", protocol)
	}
	boundary := strings.TrimSpace(spec.StepPolicy.Boundary)
	if boundary == "" {
		boundary = DefaultBoundary
	}
	if len(spec.Agents) == 0 {
		return nil, fmt.Errorf("streamma graph requires at least one agent")
	}

	graph := &compiledGraph{
		runID:        runID,
		boundary:     boundary,
		maxStepBytes: spec.StepPolicy.MaxStepBytes,
		agents:       map[string]AgentSpec{},
		predecessors: map[string][]string{},
		successors:   map[string][]string{},
		edgeIDs:      map[string]string{},
	}
	for _, agent := range spec.Agents {
		agent.ID = strings.TrimSpace(agent.ID)
		if agent.ID == "" {
			return nil, fmt.Errorf("streamma agent id is required")
		}
		if _, ok := graph.agents[agent.ID]; ok {
			return nil, fmt.Errorf("duplicate streamma agent id: %s", agent.ID)
		}
		graph.agents[agent.ID] = agent
		graph.agentOrder = append(graph.agentOrder, agent.ID)
		graph.predecessors[agent.ID] = nil
		graph.successors[agent.ID] = nil
	}
	for _, edge := range spec.Edges {
		from := strings.TrimSpace(edge.From)
		to := strings.TrimSpace(edge.To)
		if _, ok := graph.agents[from]; !ok {
			return nil, fmt.Errorf("streamma edge references unknown source agent: %s", from)
		}
		if _, ok := graph.agents[to]; !ok {
			return nil, fmt.Errorf("streamma edge references unknown target agent: %s", to)
		}
		if from == to {
			return nil, fmt.Errorf("streamma self edge is not allowed: %s", from)
		}
		key := edgeKey(from, to)
		if _, exists := graph.edgeIDs[key]; exists {
			return nil, fmt.Errorf("duplicate streamma edge: %s", key)
		}
		graph.edgeIDs[key] = key
		graph.successors[from] = append(graph.successors[from], to)
		graph.predecessors[to] = append(graph.predecessors[to], from)
	}
	for _, id := range graph.agentOrder {
		sort.Strings(graph.successors[id])
		sort.Strings(graph.predecessors[id])
		if len(graph.predecessors[id]) == 0 {
			graph.sources = append(graph.sources, id)
		}
	}
	sinkCount := 0
	for _, id := range graph.agentOrder {
		if len(graph.successors[id]) == 0 {
			sinkCount++
		}
	}
	if len(graph.sources) == 0 {
		return nil, fmt.Errorf("streamma graph has no source agent")
	}
	if sinkCount == 0 {
		return nil, fmt.Errorf("streamma graph has no sink agent")
	}
	if err := graph.validateAcyclic(); err != nil {
		return nil, err
	}
	return graph, nil
}

func (g *compiledGraph) validateAcyclic() error {
	indegree := map[string]int{}
	for _, id := range g.agentOrder {
		indegree[id] = len(g.predecessors[id])
	}
	queue := append([]string(nil), g.sources...)
	sort.Strings(queue)
	visited := 0
	for len(queue) > 0 {
		id := queue[0]
		queue = queue[1:]
		visited++
		for _, succ := range g.successors[id] {
			indegree[succ]--
			if indegree[succ] == 0 {
				queue = append(queue, succ)
				sort.Strings(queue)
			}
		}
	}
	if visited != len(g.agentOrder) {
		return fmt.Errorf("streamma graph must be a DAG")
	}
	return nil
}

func edgeKey(from, to string) string {
	return strings.TrimSpace(from) + "->" + strings.TrimSpace(to)
}

// 本文件定义 Bubble Tea 应用模型的创建、初始化和事件更新逻辑。
package bubble

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/charmbracelet/bubbles/cursor"
	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/textarea"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

// pipelinePollCmd 异步检测 .pipeline-workspace/ 并返回 pipelineStateUpdatedMsg。
func pipelinePollCmd(activeAfter time.Time) tea.Cmd {
	return func() tea.Msg {
		cwd, err := os.Getwd()
		if err != nil {
			return pipelineStateUpdatedMsg{}
		}
		workspaceDir := filepath.Join(cwd, ".pipeline-workspace")
		return pipelineStateUpdatedMsg{state: loadPipelineState(workspaceDir, activeAfter)}
	}
}

// newModel 创建完整的 TUI 状态模型，并初始化输入框、滚动区和系统消息。
func newModel(ctx context.Context, runner Runner, sessionID string, controller ModelConfigController, settingsController SettingsController, subagentController SubagentController, sessionStore SessionStore, anchor *terminalCursorAnchor) appModel {
	now := time.Now()
	input := textarea.New()
	input.Prompt = ""
	input.Placeholder = ">"
	input.ShowLineNumbers = false
	input.EndOfBufferCharacter = ' '
	input.CharLimit = 0
	input.MaxHeight = inputMaxVisibleLines
	input.SetWidth(72)
	input.SetHeight(1)
	input.KeyMap.InsertNewline = key.NewBinding(
		key.WithKeys("ctrl+j", "alt+enter", "shift+enter"),
		key.WithHelp("ctrl+j", "newline"),
	)
	input.Cursor.SetMode(cursor.CursorStatic)
	applyTextareaPlainBackground(&input)
	input.Focus()

	vp := viewport.New(80, 20)
	model := appModel{
		ctx:                 ctx,
		runner:              runner,
		sessionID:           sessionID,
		modelConfig:         controller,
		settingsConfig:      settingsController,
		subagents:           subagentController,
		sessionStore:        sessionStore,
		commandRegistry:     NewCommandRegistry(),
		cursorAnchor:        anchor,
		input:               input,
		viewport:            vp,
		cursorFrameAt:       now,
		pipelineActiveAfter: now,
		activeAssistant:     -1,
		historyIndex:        -1,
		transcript: []transcriptEntry{
			{
				kind:  entrySystem,
				title: "system",
				body:  "Interactive mode is running on Bubble Tea. Use /help for commands.",
			},
		},
	}
	model.applyCursorAnimation()
	model.refreshViewport()
	return model
}

// applyTextareaPlainBackground 移除 textarea 默认的当前行背景色，让输入文字保持透明背景。
func applyTextareaPlainBackground(input *textarea.Model) {
	plain := lipgloss.NewStyle()
	input.FocusedStyle.Base = plain
	input.FocusedStyle.CursorLine = plain
	input.FocusedStyle.Text = plain
	input.FocusedStyle.Placeholder = lipgloss.NewStyle().Foreground(colorManager.LipglossColor(colorMarkdownRule))
	input.BlurredStyle.Base = plain
	input.BlurredStyle.CursorLine = plain
	input.BlurredStyle.Text = plain
	input.BlurredStyle.Placeholder = lipgloss.NewStyle().Foreground(colorManager.LipglossColor(colorMarkdownRule))
}

// Init 返回 Bubble Tea 启动时需要执行的初始命令。
func (m appModel) Init() tea.Cmd {
	return tea.Batch(m.input.Focus(), cursorFrameTick())
}

// Update 是 Bubble Tea 的核心状态机，负责把输入事件、模型事件和工具事件规约为新状态。
func (m appModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.ready = true
		m.width = msg.Width
		m.height = msg.Height
		m.relayout()
		m.refreshViewport()
		return m, nil
	case cursorFrameMsg:
		m.cursorFrameAt = time.Time(msg)
		m.spinnerFrameIdx++
		m.applyCursorAnimation()
		m.updateContextMeterAnimation()
		if m.hasActiveTranscriptAnimation() {
			if m.viewport.AtBottom() {
				m.refreshViewport()
			} else {
				m.refreshViewportPreservingOffset()
			}
		}
		return m, tea.Batch(cursorFrameTick(), pipelinePollCmd(m.pipelineActiveAfter))
	case assistantDeltaMsg:
		m.isGenerating = true
		m.appendAssistantDelta(string(msg))
		return m, nil
	case thinkingDeltaMsg:
		m.isGenerating = true
		m.appendThinkingDelta(string(msg))
		return m, nil
	case toolCallMsg:
		m.isGenerating = false
		m.activeAssistant = -1
		m.recordToolCallEntry(msg.ID, msg.Name, json.RawMessage(msg.Input), msg.OldContent)
		return m, nil
	case toolResultMsg:
		m.activeAssistant = -1
		status := "ok"
		if msg.IsError {
			status = "error"
		}
		m.recordToolResultEntry(msg.ToolUseID, msg.Name, status, msg.IsError)
		return m, nil
	case systemEventMsg:
		title := strings.TrimSpace(msg.Title)
		if title == "" {
			title = "system"
		}
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: title,
			body:  strings.TrimSpace(msg.Body),
			color: msg.Color,
		})
		return m, nil
	case doneMsg:
		m.isGenerating = false
		m.activeAssistant = -1
		m.refreshViewport()
		return m, nil
	case turnFinishedMsg:
		m.isGenerating = false
		m.queryGuard.FinishModel()
		m.turnStartedAt = time.Time{}
		m.syncRunningFlags()
		if msg.err != nil {
			m.pendingToolCites = nil
			m.addEntry(transcriptEntry{
				kind:  entryError,
				title: "error",
				body:  msg.err.Error(),
			})
		}
		cmds = append(cmds, m.input.Focus())
		if queuedCmd := m.startNextQueuedTurn(); queuedCmd != nil {
			cmds = append(cmds, queuedCmd)
		}
	case shellFinishedMsg:
		m.queryGuard.FinishTerminal()
		m.syncRunningFlags()
		kind := entryTool
		if msg.err != nil {
			kind = entryError
		}
		m.addEntry(transcriptEntry{
			kind:  kind,
			title: "terminal",
			body:  shellResultBody(msg),
		})
		cmds = append(cmds, m.input.Focus())
	case subagentFinishedMsg:
		m.queryGuard.FinishModel()
		m.turnStartedAt = time.Time{}
		m.syncRunningFlags()
		agentTitle := resultDisplayName(msg.result)
		agentColor := strings.TrimSpace(msg.result.AgentColor)
		if msg.err != nil {
			m.addEntry(transcriptEntry{
				kind:  entryError,
				title: agentTitle,
				color: agentColor,
				body:  msg.err.Error(),
			})
		} else {
			m.addEntry(transcriptEntry{
				kind:  entrySystem,
				title: agentTitle,
				color: agentColor,
				body:  renderSubagentResult(msg.result),
			})
		}
		cmds = append(cmds, m.input.Focus())
		if queuedCmd := m.startNextQueuedTurn(); queuedCmd != nil {
			cmds = append(cmds, queuedCmd)
		}
	case sessionsLoadedMsg:
		if m.sessionPicker != nil {
			if msg.err != nil {
				m.sessionPicker.err = msg.err.Error()
			} else {
				m.sessionPicker.sessions = msg.sessions
				m.sessionPicker.loading = false
			}
		}
		return m, nil
	case sessionRestoredMsg:
		if msg.err != nil {
			m.addEntry(transcriptEntry{kind: entryError, title: "sessions", body: msg.err.Error()})
		} else {
			m.sessionID = msg.sessionID
			m.addEntry(transcriptEntry{kind: entrySystem, title: "sessions", body: fmt.Sprintf("已切换到会话: %s", msg.sessionID)})
		}
		m.sessionPicker = nil
		cmds = append(cmds, m.input.Focus())
		return m, tea.Batch(cmds...)
	case fileCompletionLoadedMsg:
		// 丢弃与当前 searchDir 不匹配的过期结果
		if m.completion != nil && m.completion.kind == completionKindFile &&
			m.completion.searchDir == msg.searchDir {
			m.completion.allItems = msg.items
			m.completion.filteredItems = msg.filtered
			m.completion.loading = false
			// 用当前 prefix 再过滤一次（加载期间前缀可能已改变）
			if m.completion.prefix != "" {
				m.completion.filteredItems = filterByPrefix(m.completion.allItems, m.completion.prefix)
			}
			if m.completion.selectedIndex >= len(m.completion.filteredItems) {
				m.completion.selectedIndex = 0
			}
			// 候选项加载完成后补全框高度变化，必须重新计算布局
			m.relayout()
		}
		return m, nil
	case pipelineStateUpdatedMsg:
		m.pipelineState = msg.state
		return m, nil
	case tea.KeyMsg:
		if isRawMouseEscapeKey(msg) {
			return m, nil
		}
		if m.settingWizard != nil {
			return m.handleSettingWizardKey(msg)
		}
		if m.modelWizard != nil {
			return m.handleModelWizardKey(msg)
		}
		if m.sessionPicker != nil {
			return m.handleSessionPickerKey(msg)
		}
		// 补全激活时：只拦截导航键和确认键，其余按键正常透传给输入框
		if m.completion != nil {
			switch msg.String() {
			case "esc":
				m.clearCompletionAndRelayout()
				return m, nil
			case "up", "ctrl+p":
				m.completion.navigateUp()
				return m, nil
			case "down", "ctrl+n":
				m.completion.navigateDown()
				return m, nil
			case "tab":
				visible := m.completion.visibleItems()
				if !m.completion.loading && len(visible) > 0 {
					selected := visible[m.completion.selectedIndex]
					if m.completion.kind == completionKindFile {
						isDir := strings.HasSuffix(selected, "/")
						if isDir {
							// 目录：不加空格，候选框保持开启以继续浏览
							m = m.applyFileCompletion(selected, false)
							if syncCmd := m.syncAtCompletion(); syncCmd != nil {
								return m, syncCmd
							}
							return m, nil
						}
						// 文件：行为与 Enter 一致（加空格 + 关闭候选框）
						m = m.applyFileCompletion(selected, true)
					} else {
						m = m.applyCommandCompletion(selected)
					}
				}
				m.clearCompletionAndRelayout()
				return m, nil
			case "enter":
				visible := m.completion.visibleItems()
				if !m.completion.loading && len(visible) > 0 {
					selected := visible[m.completion.selectedIndex]
					if m.completion.kind == completionKindFile {
						// Enter：补全路径并追加空格，结束引用
						m = m.applyFileCompletion(selected, true)
					} else {
						m = m.applyCommandCompletion(selected)
					}
				}
				m.clearCompletionAndRelayout()
				return m, nil
			}
			// 其他键：不 return，继续走下面的 switch 和 textarea 更新
		}
		switch msg.String() {
		case "ctrl+c":
			now := time.Now()
			if !m.lastCtrlCAt.IsZero() && now.Sub(m.lastCtrlCAt) < time.Second {
				// 1 秒内连按两次：退出
				m.queryGuard.Cancel()
				m.chatQueue.Clear()
				return m, tea.Quit
			}
			// 第一次按：清空输入框（不进入历史）、关闭补全框
			m.lastCtrlCAt = now
			m.input.SetValue("")
			m.input.CursorEnd()
			m.pending = nil
			m.clearCompletionAndRelayout()
			m.syncInputMode()
			m.relayout()
			return m, nil
		case "ctrl+o":
			m.showThinking = !m.showThinking
			m.refreshViewportPreservingOffset()
			return m, nil
		case "up":
			return m.handleInputVerticalNavigation(-1)
		case "down":
			return m.handleInputVerticalNavigation(1)
		case "tab":
			if m.isModelWorkRunning() {
				return m.handleQueueSubmit()
			}
		case "enter":
			return m.handleSubmit()
		}
	case tea.MouseMsg:
		if next, handled, cmd := m.handleTranscriptMouse(msg); handled {
			return next, cmd
		}
		if isMouseWheel(msg) {
			if m.isTranscriptViewportMouse(msg) {
				var viewportCmd tea.Cmd
				m.viewport, viewportCmd = m.viewport.Update(msg)
				return m, viewportCmd
			}
			return m, nil
		}
		if m.isSidebarMouse(msg) {
			return m, nil
		}
	}

	var viewportCmd tea.Cmd
	m.viewport, viewportCmd = m.viewport.Update(msg)
	cmds = append(cmds, viewportCmd)

	if !m.isTerminalWorkRunning() {
		var inputCmd tea.Cmd
		m.input, inputCmd = m.input.Update(msg)
		if isTextEditingKey(msg) {
			m.resetHistoryNavigation()
		}
		m.syncInputMode()
		m.relayout()
		cmds = append(cmds, inputCmd)

		// 每次文本变化后同步补全状态
		if isTextEditingKey(msg) {
			// / 命令补全：整个输入以 / 开头时触发
			m.syncCommandCompletion()
			// @ 文件补全：词边界 @ 触发（只要 / 补全未激活）
			if cmd := m.syncAtCompletion(); cmd != nil {
				cmds = append(cmds, cmd)
			}
			// 补全状态可能已改变（如删除 @ 后清空），需要重新计算 viewport 高度
			m.relayout()
		}
	}
	m.applyCursorAnimation()

	return m, tea.Batch(cmds...)
}

package subagent

import (
	"context"
	"encoding/json"
	"fmt"
	"gocode/internal/loop"
	"gocode/internal/model"
	"gocode/internal/session"
	"gocode/internal/settings"
	"gocode/internal/tool"
	toolexec "gocode/internal/tool/exec"
	toolfile "gocode/internal/tool/file"
	toolwebfetch "gocode/internal/tool/webfetch"
	"gocode/internal/ui"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"
)

type SettingsProvider interface {
	CurrentSettings() settings.Config
}

type Notifier interface {
	OnSystemMessage(event ui.SystemEvent) error
}

type ContextSink interface {
	SubmitSupplement(input string) bool
}

type Store interface {
	session.Store
	TranscriptPath(sessionID string) string
}

type Config struct {
	Model    loop.ModelStreamer
	Store    Store
	Root     string
	Settings SettingsProvider
	Notifier Notifier
	Context  ContextSink
	Launcher Launcher

	Depth        int
	MaxDepth     int
	ParentTaskID string
}

type Manager struct {
	model        loop.ModelStreamer
	store        Store
	root         string
	settings     SettingsProvider
	notifier     Notifier
	contextSink  ContextSink
	launcher     Launcher
	registry     taskRegistry
	depth        int
	maxDepth     int
	parentTaskID string

	startMu sync.Mutex
	mu      sync.RWMutex
	tasks   map[string]TaskSnapshot
	running map[string]Process
}

type Request struct {
	ParentSessionID string
	Prompt          string
	Description     string
	ContextMode     settings.ContextMode
	RunMode         settings.RunMode
}

type Result struct {
	AgentID        string               `json:"agent_id"`
	AgentName      string               `json:"agent_name,omitempty"`
	AgentColor     string               `json:"agent_color,omitempty"`
	SessionID      string               `json:"session_id"`
	ContextMode    settings.ContextMode `json:"context_mode"`
	RunMode        settings.RunMode     `json:"run_mode"`
	TranscriptPath string               `json:"transcript_path"`
	OutputPath     string               `json:"output_path,omitempty"`
	ExitCode       *int                 `json:"exit_code,omitempty"`
	Depth          int                  `json:"depth"`
	ParentTaskID   string               `json:"parent_task_id,omitempty"`
	Content        string               `json:"content,omitempty"`
}

type Stream struct {
	Events         <-chan model.StreamEvent
	AgentID        string
	AgentName      string
	AgentColor     string
	SessionID      string
	TranscriptPath string
	OutputPath     string
}

type TaskStatus string

const (
	TaskRunning   TaskStatus = "running"
	TaskCompleted TaskStatus = "completed"
	TaskFailed    TaskStatus = "failed"
	TaskStopped   TaskStatus = "stopped"
)

type TaskSnapshot struct {
	ID              string               `json:"id"`
	Name            string               `json:"name,omitempty"`
	Color           string               `json:"color,omitempty"`
	SessionID       string               `json:"session_id"`
	ParentSessionID string               `json:"parent_session_id,omitempty"`
	Description     string               `json:"description,omitempty"`
	Prompt          string               `json:"prompt"`
	ContextMode     settings.ContextMode `json:"context_mode"`
	RunMode         settings.RunMode     `json:"run_mode"`
	Status          TaskStatus           `json:"status"`
	TranscriptPath  string               `json:"transcript_path"`
	OutputPath      string               `json:"output_path,omitempty"`
	PID             int                  `json:"pid,omitempty"`
	ExitCode        *int                 `json:"exit_code,omitempty"`
	Depth           int                  `json:"depth"`
	ParentTaskID    string               `json:"parent_task_id,omitempty"`
	StartedAt       time.Time            `json:"started_at"`
	FinishedAt      *time.Time           `json:"finished_at,omitempty"`
	Content         string               `json:"content,omitempty"`
	Error           string               `json:"error,omitempty"`
	UsedTokens      int                  `json:"used_tokens,omitempty"`
}

type sinkUI struct{}

var _ ui.UI = sinkUI{}

func NewManager(cfg Config) *Manager {
	m := &Manager{
		model:        cfg.Model,
		store:        cfg.Store,
		root:         cfg.Root,
		settings:     cfg.Settings,
		notifier:     cfg.Notifier,
		contextSink:  cfg.Context,
		launcher:     cfg.Launcher,
		registry:     newTaskRegistry(cfg.Root),
		depth:        cfg.Depth,
		maxDepth:     cfg.MaxDepth,
		parentTaskID: strings.TrimSpace(cfg.ParentTaskID),
		tasks:        make(map[string]TaskSnapshot),
		running:      make(map[string]Process),
	}
	if m.maxDepth <= 0 {
		m.maxDepth = 4
	}
	if m.launcher == nil && m.model != nil {
		m.launcher = newInProcessLauncher(m.runWorkerInProcess)
	}
	return m
}

func (m *Manager) Run(ctx context.Context, req Request) (Result, error) {
	req = m.normalizeRequest(req)
	req.RunMode = settings.RunModeSync
	if err := validateRequest(req); err != nil {
		return Result{}, err
	}
	if err := m.validate(); err != nil {
		return Result{}, err
	}

	task, process, err := m.startTask(ctx, req)
	if err != nil {
		return Result{}, err
	}
	workerResult, waitErr := process.Wait()
	task = m.finishTask(ctx, task.ID, workerResult, waitErr)
	result := resultFromTask(task)
	if waitErr != nil {
		return result, waitErr
	}
	return result, nil
}

func (m *Manager) Stream(ctx context.Context, req Request) (Stream, error) {
	if err := ctx.Err(); err != nil {
		return Stream{}, err
	}
	req = m.normalizeRequest(req)
	req.RunMode = settings.RunModeSync
	if err := validateRequest(req); err != nil {
		return Stream{}, err
	}
	if err := m.validateStreaming(); err != nil {
		return Stream{}, err
	}

	task, err := m.startStreamingTask(ctx, req)
	if err != nil {
		return Stream{}, err
	}

	events := make(chan model.StreamEvent)
	go m.runStreamingTask(ctx, task, events)

	return Stream{
		Events:         events,
		AgentID:        task.SessionID,
		AgentName:      task.Name,
		AgentColor:     task.Color,
		SessionID:      task.SessionID,
		TranscriptPath: task.TranscriptPath,
		OutputPath:     task.OutputPath,
	}, nil
}

func (m *Manager) Launch(ctx context.Context, req Request) (TaskSnapshot, error) {
	if err := ctx.Err(); err != nil {
		return TaskSnapshot{}, err
	}
	req = m.normalizeRequest(req)
	req.RunMode = settings.RunModeBackground
	if err := validateRequest(req); err != nil {
		return TaskSnapshot{}, err
	}
	if err := m.validate(); err != nil {
		return TaskSnapshot{}, err
	}

	task, process, err := m.startTask(context.Background(), req)
	if err != nil {
		return TaskSnapshot{}, err
	}
	go m.waitBackground(task.ID, process)
	return task, nil
}

func (m *Manager) Stop(ctx context.Context, id string) (TaskSnapshot, error) {
	if err := ctx.Err(); err != nil {
		return TaskSnapshot{}, err
	}
	id = strings.TrimSpace(id)
	if id == "" {
		return TaskSnapshot{}, fmt.Errorf("subagent task id is required")
	}

	m.mu.RLock()
	process, ok := m.running[id]
	task, taskOK := m.tasks[id]
	m.mu.RUnlock()
	if !taskOK {
		var loadErr error
		task, taskOK, loadErr = m.registry.loadTask(ctx, id)
		if loadErr != nil {
			return TaskSnapshot{}, loadErr
		}
	}
	if !taskOK {
		return TaskSnapshot{}, fmt.Errorf("subagent task not found: %s", id)
	}
	if task.Status != TaskRunning {
		return task, fmt.Errorf("subagent task %s is not running (status=%s)", id, task.Status)
	}

	if ok && process != nil {
		_ = process.Stop()
	}

	now := time.Now().UTC()
	exitCode := -1
	task.Status = TaskStopped
	task.FinishedAt = &now
	task.ExitCode = &exitCode
	task.Error = "stopped"

	m.mu.Lock()
	m.tasks[id] = task
	delete(m.running, id)
	m.mu.Unlock()

	_ = m.registry.saveTask(ctx, task)
	_ = m.registry.saveOutput(ctx, id, WorkerResult{
		TaskID:    id,
		SessionID: task.SessionID,
		Error:     task.Error,
		ExitCode:  exitCode,
	})
	m.notifyTaskFinished(task)
	return task, nil
}

func (m *Manager) Status(id string) (TaskSnapshot, bool) {
	id = strings.TrimSpace(id)
	m.mu.RLock()
	task, ok := m.tasks[id]
	m.mu.RUnlock()
	if ok {
		return task, true
	}
	task, ok, err := m.registry.loadTask(context.Background(), id)
	if err != nil {
		return TaskSnapshot{}, false
	}
	return task, ok
}

func (m *Manager) ListTasks() []TaskSnapshot {
	m.mu.RLock()
	tasksByID := make(map[string]TaskSnapshot, len(m.tasks))
	for _, task := range m.tasks {
		tasksByID[task.ID] = task
	}
	m.mu.RUnlock()

	diskTasks, err := m.registry.listTasks(context.Background())
	if err == nil {
		for _, task := range diskTasks {
			if _, ok := tasksByID[task.ID]; !ok {
				tasksByID[task.ID] = task
			}
		}
	}

	tasks := make([]TaskSnapshot, 0, len(tasksByID))
	for _, task := range tasksByID {
		tasks = append(tasks, task)
	}
	sort.Slice(tasks, func(i, j int) bool {
		return tasks[i].StartedAt.Before(tasks[j].StartedAt)
	})
	return tasks
}

// TotalSubagentTokens returns the sum of UsedTokens for all completed tasks
// whose ParentSessionID matches the given session ID.
func (m *Manager) TotalSubagentTokens(parentSessionID string) int {
	if m == nil || parentSessionID == "" {
		return 0
	}
	m.mu.RLock()
	defer m.mu.RUnlock()
	total := 0
	for _, task := range m.tasks {
		if task.ParentSessionID == parentSessionID {
			total += task.UsedTokens
		}
	}
	return total
}

func (m *Manager) normalizeRequest(req Request) Request {
	cfg := settings.DefaultConfig()
	if m != nil && m.settings != nil {
		cfg = m.settings.CurrentSettings()
	}
	if req.ContextMode == "" {
		req.ContextMode = cfg.Subagent.DefaultContextMode
	}
	if req.RunMode == "" {
		req.RunMode = cfg.Subagent.DefaultRunMode
	}
	req.ContextMode = settings.NormalizeContextMode(req.ContextMode)
	req.RunMode = settings.NormalizeRunMode(req.RunMode)
	req.Prompt = strings.TrimSpace(req.Prompt)
	req.Description = strings.TrimSpace(req.Description)
	return req
}

func validateRequest(req Request) error {
	if strings.TrimSpace(req.Prompt) == "" {
		return fmt.Errorf("prompt is required")
	}
	if req.ContextMode == settings.ContextModeFork && strings.TrimSpace(req.ParentSessionID) == "" {
		return fmt.Errorf("parent_session_id is required for fork context")
	}
	return nil
}

func (m *Manager) validate() error {
	if m == nil {
		return fmt.Errorf("subagent manager is nil")
	}
	if m.launcher == nil {
		return fmt.Errorf("subagent launcher is nil")
	}
	if m.store == nil {
		return fmt.Errorf("subagent store is nil")
	}
	if strings.TrimSpace(m.root) == "" {
		return fmt.Errorf("subagent root is empty")
	}
	return nil
}

func (m *Manager) validateStreaming() error {
	if m == nil {
		return fmt.Errorf("subagent manager is nil")
	}
	if m.model == nil {
		return fmt.Errorf("subagent streaming model is nil")
	}
	if m.store == nil {
		return fmt.Errorf("subagent store is nil")
	}
	if strings.TrimSpace(m.root) == "" {
		return fmt.Errorf("subagent root is empty")
	}
	return nil
}

func (m *Manager) startTask(ctx context.Context, req Request) (TaskSnapshot, Process, error) {
	m.startMu.Lock()
	defer m.startMu.Unlock()

	depth := m.depth + 1
	if depth > m.maxDepth {
		return TaskSnapshot{}, nil, fmt.Errorf("subagent depth limit exceeded: %d > %d", depth, m.maxDepth)
	}

	persona, err := m.assignPersona(ctx)
	if err != nil {
		return TaskSnapshot{}, nil, err
	}

	sessionID, err := m.prepareSession(ctx, req)
	if err != nil {
		return TaskSnapshot{}, nil, err
	}

	task := TaskSnapshot{
		ID:              sessionID,
		Name:            persona.Name,
		Color:           persona.Color,
		SessionID:       sessionID,
		ParentSessionID: strings.TrimSpace(req.ParentSessionID),
		Description:     req.Description,
		Prompt:          req.Prompt,
		ContextMode:     req.ContextMode,
		RunMode:         req.RunMode,
		Status:          TaskRunning,
		TranscriptPath:  m.store.TranscriptPath(sessionID),
		OutputPath:      m.registry.outputPath(sessionID),
		Depth:           depth,
		ParentTaskID:    m.parentTaskID,
		StartedAt:       time.Now().UTC(),
	}
	workerReq := WorkerRequest{
		TaskID:          task.ID,
		SessionID:       task.SessionID,
		ParentSessionID: strings.TrimSpace(req.ParentSessionID),
		ParentTaskID:    task.ParentTaskID,
		Prompt:          req.Prompt,
		Description:     req.Description,
		ContextMode:     req.ContextMode,
		RunMode:         req.RunMode,
		Depth:           task.Depth,
		MaxDepth:        m.maxDepth,
	}

	if err := m.registry.saveTask(ctx, task); err != nil {
		return TaskSnapshot{}, nil, err
	}
	m.setTask(task)

	process, err := m.launcher.Start(ctx, workerReq)
	if err != nil {
		task.Status = TaskFailed
		task.Error = err.Error()
		now := time.Now().UTC()
		exitCode := 1
		task.FinishedAt = &now
		task.ExitCode = &exitCode
		m.setTask(task)
		_ = m.registry.saveTask(ctx, task)
		_ = m.registry.saveOutput(ctx, task.ID, WorkerResult{
			TaskID:    task.ID,
			SessionID: task.SessionID,
			Error:     task.Error,
			ExitCode:  exitCode,
		})
		return TaskSnapshot{}, nil, err
	}
	task.PID = process.PID()
	m.mu.Lock()
	m.tasks[task.ID] = task
	m.running[task.ID] = process
	m.mu.Unlock()
	if err := m.registry.saveTask(ctx, task); err != nil {
		_ = process.Stop()
		now := time.Now().UTC()
		exitCode := 1
		task.Status = TaskFailed
		task.Error = err.Error()
		task.FinishedAt = &now
		task.ExitCode = &exitCode
		m.mu.Lock()
		m.tasks[task.ID] = task
		delete(m.running, task.ID)
		m.mu.Unlock()
		_ = m.registry.saveOutput(ctx, task.ID, WorkerResult{
			TaskID:    task.ID,
			SessionID: task.SessionID,
			Error:     task.Error,
			ExitCode:  exitCode,
		})
		_ = m.registry.saveTask(ctx, task)
		return TaskSnapshot{}, nil, err
	}
	return task, process, nil
}

func (m *Manager) startStreamingTask(ctx context.Context, req Request) (TaskSnapshot, error) {
	m.startMu.Lock()
	defer m.startMu.Unlock()

	depth := m.depth + 1
	if depth > m.maxDepth {
		return TaskSnapshot{}, fmt.Errorf("subagent depth limit exceeded: %d > %d", depth, m.maxDepth)
	}

	persona, err := m.assignPersona(ctx)
	if err != nil {
		return TaskSnapshot{}, err
	}

	sessionID, err := m.prepareSession(ctx, req)
	if err != nil {
		return TaskSnapshot{}, err
	}

	task := TaskSnapshot{
		ID:              sessionID,
		Name:            persona.Name,
		Color:           persona.Color,
		SessionID:       sessionID,
		ParentSessionID: strings.TrimSpace(req.ParentSessionID),
		Description:     req.Description,
		Prompt:          req.Prompt,
		ContextMode:     req.ContextMode,
		RunMode:         req.RunMode,
		Status:          TaskRunning,
		TranscriptPath:  m.store.TranscriptPath(sessionID),
		OutputPath:      m.registry.outputPath(sessionID),
		PID:             os.Getpid(),
		Depth:           depth,
		ParentTaskID:    m.parentTaskID,
		StartedAt:       time.Now().UTC(),
	}

	if err := m.registry.saveTask(ctx, task); err != nil {
		return TaskSnapshot{}, err
	}
	m.setTask(task)
	return task, nil
}

func (m *Manager) runStreamingTask(ctx context.Context, task TaskSnapshot, events chan<- model.StreamEvent) {
	defer close(events)

	content, usedTokens, done, err := m.runStreamingSession(ctx, task.SessionID, task.Prompt, events)
	result := WorkerResult{
		TaskID:     task.ID,
		SessionID:  task.SessionID,
		Content:    content,
		ExitCode:   0,
		UsedTokens: usedTokens,
	}
	if err != nil {
		result.Error = err.Error()
		result.ExitCode = 1
		if !done {
			_ = sendModelStreamEvent(context.Background(), events, model.StreamEvent{Err: err})
		}
	}
	m.finishTask(context.Background(), task.ID, result, err)
}

func (m *Manager) waitBackground(taskID string, process Process) {
	result, err := process.Wait()
	task := m.finishTask(context.Background(), taskID, result, err)
	m.notifyTaskFinished(task)
}

func (m *Manager) finishTask(ctx context.Context, taskID string, result WorkerResult, err error) TaskSnapshot {
	now := time.Now().UTC()
	m.mu.Lock()
	task := m.tasks[taskID]
	if task.ID == "" {
		task.ID = taskID
		task.SessionID = result.SessionID
		task.OutputPath = m.registry.outputPath(taskID)
	}
	if task.Status != TaskRunning {
		delete(m.running, taskID)
		m.mu.Unlock()
		return task
	}
	exitCode := result.ExitCode
	if exitCode == 0 && err != nil {
		exitCode = 1
	}
	task.FinishedAt = &now
	task.ExitCode = &exitCode
	if result.Content != "" {
		task.Content = strings.TrimSpace(result.Content)
	}
	if result.UsedTokens > 0 {
		task.UsedTokens = result.UsedTokens
	}
	if err != nil || result.Error != "" {
		task.Status = TaskFailed
		task.Error = strings.TrimSpace(result.Error)
		if task.Error == "" && err != nil {
			task.Error = err.Error()
		}
	} else {
		task.Status = TaskCompleted
	}
	m.tasks[taskID] = task
	delete(m.running, taskID)
	m.mu.Unlock()

	_ = m.registry.saveOutput(ctx, taskID, result)
	_ = m.registry.saveTask(ctx, task)
	m.submitTaskContext(task)
	return task
}

func (m *Manager) prepareSession(ctx context.Context, req Request) (string, error) {
	sessionID, err := session.GenerateSessionID()
	if err != nil {
		return "", err
	}
	switch req.ContextMode {
	case settings.ContextModeFork:
		parentID := strings.TrimSpace(req.ParentSessionID)
		if err := m.ensureSessionExists(ctx, parentID); err != nil {
			return "", err
		}
		if _, err := m.store.Fork(ctx, session.ForkRequest{
			SessionID:       sessionID,
			ParentSessionID: parentID,
			ForkFromSeq:     -1,
		}); err != nil {
			return "", err
		}
	default:
		if _, err := m.store.CreateRoot(ctx, session.CreateRootRequest{SessionID: sessionID}); err != nil {
			return "", err
		}
	}
	return sessionID, nil
}

func (m *Manager) ensureSessionExists(ctx context.Context, sessionID string) error {
	if strings.TrimSpace(sessionID) == "" {
		return fmt.Errorf("parent session id is required")
	}
	exists, err := m.store.Exists(ctx, sessionID)
	if err != nil {
		return err
	}
	if exists {
		return nil
	}
	if _, err := m.store.CreateRoot(ctx, session.CreateRootRequest{SessionID: sessionID}); err != nil {
		return err
	}
	return nil
}

func (m *Manager) runSession(ctx context.Context, sessionID, prompt string) (string, error) {
	runner := loop.NewRunnerWithInstructionRoot(m.model, sinkUI{}, newBaseToolRegistry(m.root), m.store, sessionID, m.root)
	msg, err := runner.RunTurn(ctx, prompt)
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(msg.Content), nil
}

func (m *Manager) runStreamingSession(ctx context.Context, sessionID, prompt string, events chan<- model.StreamEvent) (string, int, bool, error) {
	streamUI := &streamingUI{ctx: ctx, events: events}
	runner := loop.NewRunnerWithInstructionRoot(m.model, streamUI, newBaseToolRegistry(m.root), m.store, sessionID, m.root)
	msg, err := runner.RunTurn(ctx, prompt)
	usedTokens := runner.ContextStats(1<<30, "").UsedTokens
	done := streamUI.Done()
	if err != nil {
		return "", usedTokens, done, err
	}
	return strings.TrimSpace(msg.Content), usedTokens, done, nil
}

func (m *Manager) runWorkerInProcess(ctx context.Context, req WorkerRequest) (WorkerResult, error) {
	content, err := m.runSession(ctx, req.SessionID, req.Prompt)
	result := WorkerResult{
		TaskID:    req.TaskID,
		SessionID: req.SessionID,
		Content:   content,
		ExitCode:  0,
	}
	if err != nil {
		result.Error = err.Error()
		result.ExitCode = 1
		return result, err
	}
	return result, nil
}

func (m *Manager) setTask(task TaskSnapshot) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.tasks[task.ID] = task
}

func (m *Manager) notifyTaskFinished(task TaskSnapshot) {
	if m == nil || m.notifier == nil {
		return
	}
	status := string(task.Status)
	body := fmt.Sprintf("%s finished with status=%s", shortID(task.ID), status)
	if task.Error != "" {
		body += ": " + task.Error
	} else if task.Content != "" {
		body += ": " + summarize(task.Content)
	}
	_ = m.notifier.OnSystemMessage(ui.SystemEvent{
		Title: "subagent",
		Body:  body,
	})
}

const parentContextResultMaxRunes = 6000

func (m *Manager) submitTaskContext(task TaskSnapshot) {
	if m == nil || m.contextSink == nil || task.RunMode != settings.RunModeBackground {
		return
	}
	if strings.TrimSpace(task.ParentSessionID) == "" {
		return
	}
	update := renderTaskContextUpdate(task)
	if strings.TrimSpace(update) == "" {
		return
	}
	_ = m.contextSink.SubmitSupplement(update)
}

func renderTaskContextUpdate(task TaskSnapshot) string {
	var lines []string
	lines = append(lines, "Background subagent completed.")
	lines = append(lines, "id: "+task.ID)
	if task.Name != "" {
		lines = append(lines, "name: "+task.Name)
	}
	if task.Description != "" {
		lines = append(lines, "description: "+task.Description)
	}
	lines = append(lines, "status: "+string(task.Status))
	lines = append(lines, "context_mode: "+string(task.ContextMode))
	lines = append(lines, "run_mode: "+string(task.RunMode))
	if task.TranscriptPath != "" {
		lines = append(lines, "transcript: "+task.TranscriptPath)
	}
	if task.OutputPath != "" {
		lines = append(lines, "output: "+task.OutputPath)
	}
	if task.Error != "" {
		lines = append(lines, "error: "+task.Error)
	}
	content := strings.TrimSpace(task.Content)
	if content != "" {
		lines = append(lines, "result:")
		lines = append(lines, truncateForParentContext(content, parentContextResultMaxRunes, task.OutputPath))
	}
	return strings.Join(lines, "\n")
}

func truncateForParentContext(content string, limit int, outputPath string) string {
	if limit <= 0 {
		limit = parentContextResultMaxRunes
	}
	runes := []rune(content)
	if len(runes) <= limit {
		return content
	}
	suffix := "\n[truncated]"
	if outputPath != "" {
		suffix = "\n[truncated; full result: " + outputPath + "]"
	}
	return string(runes[:limit]) + suffix
}

func resultFromTask(task TaskSnapshot) Result {
	return Result{
		AgentID:        task.SessionID,
		AgentName:      task.Name,
		AgentColor:     task.Color,
		SessionID:      task.SessionID,
		ContextMode:    task.ContextMode,
		RunMode:        task.RunMode,
		TranscriptPath: task.TranscriptPath,
		OutputPath:     task.OutputPath,
		ExitCode:       task.ExitCode,
		Depth:          task.Depth,
		ParentTaskID:   task.ParentTaskID,
		Content:        task.Content,
	}
}

func newBaseToolRegistry(root string) *tool.Registry {
	registry := tool.NewRegistry()
	registry.Register(&toolfile.LSTool{Root: root})
	registry.Register(&toolfile.ReadTool{Root: root})
	registry.Register(&toolfile.WriteTool{Root: root})
	registry.Register(&toolfile.GrepTool{Root: root})
	registry.Register(&toolfile.GlobTool{Root: root})
	registry.Register(&toolexec.BashTool{Root: root})
	registry.Register(&toolwebfetch.Tool{})
	return registry
}

func shortID(id string) string {
	if len(id) <= 8 {
		return id
	}
	return id[:8]
}

func summarize(text string) string {
	fields := strings.Join(strings.Fields(text), " ")
	runes := []rune(fields)
	if len(runes) <= 160 {
		return fields
	}
	return string(runes[:160]) + "..."
}

